/**
 * Optional, connector-backed capabilities shared by all modules. Modules
 * call them through useServices() and must cope with a service being absent.
 * The app wires real implementations in src/services.ts, typically on top
 * of services generated by `pa app add data-source --connector <connector>`
 * (Office 365 Outlook, Teams, Office 365 Users, ...) or `pa app add flow`.
 */
export interface NotificationInput {
  /** Recipients' user principal names. */
  toUpns: string[]
  subject: string
  /** Plain text. */
  body: string
  /** Deep link back into the app. */
  link?: string
}

export interface NotificationService {
  notify(input: NotificationInput): Promise<void>
}

export interface WorkspaceServices {
  notifications?: NotificationService
}
